@startuml

class Resident {
  + name : string
  + street_address : string
  + phone_number : string
  + email : string
}

class Item {
  + description : string
  + weight : float
  + dimensions : string
  + category : string
}

class PickupRequest {
  + street_address : string
  + pickup_day : date
  + pickup_time_window : string
}

class Vehicle {
  + storage_space : float
}

class Route {
  + date : date
}

class VolunteerDriver {
  + available_days : string[]
}

class H2SLocation {
}

class DistributionCenter extends H2SLocation {
}

class FoodBank {
}

class H2SEmployee {
}

class Client {
  + home_address : string
  + needed_categories : string[]
}

class Article {
  + rfid_tag : string
  + description : string
  + category : string
}

class Delivery {
}

Resident "1" -- "*" PickupRequest : schedules
PickupRequest "1" -- "*" Item : includes
Vehicle "1" -- "*" Route : follows
VolunteerDriver "1" -- "*" Route : drives
Route "1" -- "*" PickupRequest : includes
Route "1" -- "*" Delivery : includes
VolunteerDriver "1" -- "*" Delivery : performs
DistributionCenter "1" -- "*" Article : receives
H2SEmployee "1" -- "*" Article : examines
H2SEmployee "1" -- "*" Delivery : arranges
Client "1" -- "*" Article : receives
Client "0..1" -- "1" DistributionCenter : served_by
H2SLocation "1" -- "*" DistributionCenter : operates_in
H2SLocation "1" -- "*" FoodBank : operates_in

@enduml

